import Header from './components/Header';
import styled from 'styled-components'
import Pesquisa from './components/Pesquisa';

 const AppContainer = styled.div `
    width: 100vw;
    height: 100vh;
    background-image: linear-gradient(90deg,rgb(53, 156, 235) 35%,rgb(82, 163, 221) 165% );

    li {
    list-style: none;
}
 `



function App() {
  return (
    <div AppContainer="App">
     <Header />
     <Pesquisa />

    </div>

  );
}

export default App;
